import * as fs from "fs";
import * as path from "path";
import { MedusaContainer } from "@medusajs/framework";
import { ContainerRegistrationKeys } from "@medusajs/framework/utils";
import { updateProductsWorkflow } from "@medusajs/medusa/core-flows";

// Every uploaded product image already has a .webp twin on disk now
// (converted in place with cwebp -q 82, originals kept untouched - see
// webp_mapping.tsv, generated by a one-off shell pass over /uploads, not
// committed to git since it's a run-specific artifact). This only rewrites
// each product/variant's image URL from the old filename to its .webp
// twin - no bytes are re-read or re-uploaded, both files already live at
// the same /uploads path the local file provider serves from.
//
// DRY_RUN prints what WOULD change without calling updateProductsWorkflow -
// run that first and read the counts/samples before flipping it off.
const DRY_RUN = false;

const MAPPING_FILE = path.resolve(__dirname, "../../../../webp_mapping.tsv");

function loadMapping(): Map<string, string> {
  const raw = fs.readFileSync(MAPPING_FILE, "utf8");
  const map = new Map<string, string>();
  for (const line of raw.split("\n")) {
    if (!line.startsWith("OK")) continue;
    // the bulk-converted lines have a literal two-char "\t" (the shell
    // script's `echo` didn't interpret escapes); the one hand-fixed entry
    // (a filename with real spaces) has an actual tab from `printf`.
    const parts = line.includes("\t") ? line.split("\t") : line.split("\\t");
    if (parts.length < 3) continue;
    const oldName = parts[1].trim();
    const newName = parts[2].trim();
    if (oldName && newName) map.set(oldName, newName);
  }
  return map;
}

// Product image URLs are same-origin relative paths like
// "/static/<filename>" (see toStorefrontMediaUrl) - pull the filename off
// the end, decode it (the local file provider doesn't appear to encode
// spaces, but handle it defensively either way) and look it up.
function swap(url: string | null | undefined, map: Map<string, string>): string | null {
  if (!url) return null;
  const base = url.split("/").pop() || ""
  let decoded = base
  try {
    decoded = decodeURIComponent(base)
  } catch {
    // not URL-encoded - use as-is
  }
  const newName = map.get(decoded) || map.get(base)
  if (!newName) return null
  const prefix = url.slice(0, url.length - base.length)
  return prefix + encodeURIComponent(newName)
}

export default async function convert_images_to_webp({
  container,
}: {
  container: MedusaContainer;
}) {
  const logger = container.resolve(ContainerRegistrationKeys.LOGGER);
  const query = container.resolve(ContainerRegistrationKeys.QUERY);

  const map = loadMapping();
  logger.info(`Loaded ${map.size} filename mappings. DRY_RUN=${DRY_RUN}`);

  const { data: products } = await query.graph({
    entity: "product",
    fields: ["id", "title", "thumbnail", "images.id", "images.url"],
  });

  let updated = 0;
  let skipped = 0;
  let failed = 0;
  const samples: string[] = [];

  for (const product of products as any[]) {
    try {
      const newThumbnail = swap(product.thumbnail, map);
      const images = product.images || [];
      const newImages = images.map((img: any) => ({
        url: swap(img.url, map) || img.url,
      }));
      const anyImageChanged = images.some(
        (img: any, i: number) => newImages[i].url !== img.url
      );
      const thumbChanged = !!newThumbnail && newThumbnail !== product.thumbnail;

      if (!thumbChanged && !anyImageChanged) {
        skipped++;
        continue;
      }

      if (samples.length < 5) {
        samples.push(
          `${product.title}: thumbnail ${product.thumbnail} -> ${newThumbnail ?? "(unchanged)"}`
        );
      }

      if (!DRY_RUN) {
        await updateProductsWorkflow(container).run({
          input: {
            products: [
              {
                id: product.id,
                ...(thumbChanged ? { thumbnail: newThumbnail } : {}),
                ...(images.length ? { images: newImages } : {}),
              } as any,
            ],
          },
        });
      }
      updated++;
    } catch (e: any) {
      failed++;
      logger.info(`FAILED ${product.id} (${product.title}): ${String(e?.message || e)}`);
    }
  }

  logger.info(
    `${DRY_RUN ? "[DRY RUN] Would update" : "Updated"}: ${updated}, skipped (no matching image): ${skipped}, failed: ${failed}.`
  );
  if (samples.length) {
    logger.info(`Samples:\n${samples.join("\n")}`);
  }
}
